import io.ktor.client.request.get
import io.ktor.client.request.header
import io.ktor.client.statement.HttpResponse
import io.ktor.http.HttpStatusCode

class CitiesRemoteDataSourceImp(
 private val httpClient: HttpClient
) : CitiesRemoteDataSource {

 override suspend fun fetchCities(): ResultData<List<CityRemoteModel>> {
 return try {
 val response: HttpResponse = httpClient.get(
 "https://raw.githubusercontent.com/mbanifawaz/Jordan_Prayer_Times_API_Data/main/cities/cities.json"
 ) {
 header(
 "Authorization",
 "Bearer REMOVED_TOKEN"
 )
 }

 when (response.status) {
 HttpStatusCode.OK -> {
 val cities: List<CityRemoteModel> = response.body()
 ResultData.Success(cities)
 }
 else -> {
 ResultData.Error(
 ErrorEntity.ApiError(
 code = response.status.value,
 message = listOf("Failed to fetch cities")
 )
 )
 }
 }
 } catch (e: Exception) {
 ResultData.Error(
 ErrorEntity.InternalError(
 message = e.message ?: "Unknown error occurred"
 )
 )
 }
 }
}

