import com.mbf.wearable.jordanprayertimes.data.ui.CityUiModel
import com.mbf.wearable.jordanprayertimes.presentation.SettingsViewModel
import org.koin.androidx.compose.koinViewModel

@Composable
fun SettingsScreen() {
 val viewModel = koinViewModel<SettingsViewModel>()
 val uiState by viewModel.uiState.collectAsStateWithLifecycle()
 val listState = rememberScalingLazyListState()

 // Memoize cities list to prevent unnecessary recompositions
 val cities = remember(uiState.cities) { uiState.cities }
 val selectedCityId = remember(uiState.selectedCity?.id) { uiState.selectedCity?.id ?: 0 }
 val notificationsEnabled = remember(uiState.notificationsEnabled) { uiState.notificationsEnabled }

 if (uiState.isLoading) {
 Box(
 modifier = Modifier.fillMaxSize(),
 contentAlignment = androidx.compose.ui.Alignment.Center
 ) {
 CircularProgressIndicator()
 }
 return
 }

 ScalingLazyColumn(
 modifier = Modifier.fillMaxSize(),
 state = listState
 ) {
 item(key = "notifications_toggle") {
 NotificationToggle(
 notificationsEnabled = notificationsEnabled,
 onToggle = { enabled ->
 viewModel.actionTrigger(SettingsViewModel.UIAction.ToggleNotifications(enabled))
 }
 )
 }

 item(key = "divider") {
 SettingsDivider()
 }

 item(key = "cities_header") {
 Text(
 text = "Cities",
 modifier = Modifier,
 style = MaterialTheme.typography.title3
 )
 }

 items(
 items = cities,
 key = { city -> city.id }
 ) { city ->
 CityChip(
 city = city,
 isSelected = city.id == selectedCityId,
 onCitySelected = {
 viewModel.actionTrigger(SettingsViewModel.UIAction.SelectCity(city))
 }
 )
 }
 }
}

/**
 * Notification toggle - isolated to prevent recomposition
 */
@Composable
private fun NotificationToggle(
 notificationsEnabled: Boolean,
 onToggle: (Boolean) -> Unit
) {
 ToggleChip(
 checked = notificationsEnabled,
 onCheckedChange = onToggle,
 label = {
 Text(
 "Enable Notifications",
 fontSize = 12.sp
 )
 },
 toggleControl = {
 Switch(
 checked = notificationsEnabled,
 onCheckedChange = null,
 colors = SwitchDefaults.colors(
 checkedThumbColor = Color.Cyan,
 )
 )
 },
 modifier = Modifier
 .fillMaxWidth()
 .padding(horizontal = 8.dp)
 )
}

/**
 * Divider - isolated as a separate composable
 */
@Composable
private fun SettingsDivider() {
 Box(
 modifier = Modifier
 .fillMaxWidth()
 .height(1.dp)
 .background(MaterialTheme.colors.surface)
 .padding(vertical = 16.dp)
 )
}

/**
 * City chip - isolated and optimized with stable parameters
 */
@Composable
private fun CityChip(
 city: CityUiModel,
 isSelected: Boolean,
 onCitySelected: () -> Unit
) {
 // Remember city properties to avoid recomposition
 val cityName = remember(city.id) { city.name }

 Chip(
 modifier = Modifier.fillMaxWidth(),
 onClick = onCitySelected,
 label = {
 Text(
 text = cityName,
 maxLines = 1,
 overflow = TextOverflow.Ellipsis
 )
 },
 colors = ChipDefaults.chipColors(
 backgroundColor = if (isSelected) {
 Color.Cyan.copy(alpha = 0.8f)
 } else {
 Color.Gray
 }
 )
 )
}

@WearPreviewDevices
@Composable
fun PreviewSettingsScreen() {
 // Preview removed - requires proper setup
}
