class KtorSetup(
 private val appConfig: AppConfig,
 private val appPref: AppPref,
 private val favouriteLocalCache: FavouriteLocalCache,
 private val jwtAuth: JwtAuth,
 private val defaultJson: Json,
 private val userDefaultToken: String,
 private val baseUrl: String
) {

 private val APP_UUID_HEADER_KEY = "app_request_id"

 @OptIn(ExperimentalUuidApi::class)
 fun getHTTPClient(): HttpClient {

 return HttpClient {

 install(ContentNegotiation) {
 json(
 defaultJson // located in AppModule.kt
 )
 }

 if (isDebug() && getPlatform().platformName == PlatformName.Android) {
 install(Inspektor)
 }

 install(Logging) {
 logger = Logger.DEFAULT
 level = LogLevel.ALL
 logger = object : Logger {
 override fun log(message: String) {
 AppLogger.i(message = "Ktor: $message")
 }
 }
 }

 install(createClientPlugin("SyarahV1Plugin") {
 onRequest { request, content ->
 request.headers.append(
 "uuid",
 appPref.getDeviceUniqueId().ifEmpty { appPref.getDeviceUUID() })
 if (request.url.pathSegments.contains("syarah_v1") || request.url.pathSegments.contains(
 "search_v1"
 )
 )
 appPref.getUserToken()?.let { token ->
 request.headers.append(
 "Authorization",
 "Bearer $token"
 )
 } ?: run {
 request.headers.append("token", userDefaultToken)
 }

 request.headers.append(APP_UUID_HEADER_KEY, Uuid.random().toHexString())

 }
 onResponse {
 if (it.headers.contains("x-country-code")) {
 appPref.setCountry(it.headers["x-country-code"] ?: "")
 }
 }
 })

 install(createClientPlugin("HeadlessCmsPlugin") {
 onRequest { request, content ->
 if (request.url.pathSegments.contains("headlesscms_v1"))
 request.headers.append("token", userDefaultToken)
 }
 })

 install(HttpRequestRetry) {
 maxRetries = 2
 retryIf { request, response ->
 if (response.status in arrayOf(
 HttpStatusCode.Unauthorized
 )
 ) {
 logHTTPClient("Retry(): ${request.url.encodedPath} with status ${response.status}")
 return@retryIf try {
 request.call.launch {
 logHTTPClient("Retry(): trying to logout")
 appPref.clear()
 favouriteLocalCache.clear()
 }
 true
 } catch (e: Exception) {
 logHTTPClient("Retry(): logout error ${e.message}")
 false
 }
 } else false
 }

 delayMillis { retry ->
 retry * 2000L
 }

 modifyRequest { request ->
 logHTTPClient("Retry(): modify Request with new token")
 request.headers.remove(HttpHeaders.Authorization)
 request.headers.append("token", userDefaultToken)
 }
 }

 install(ktorLanguagePlugin(appPref = appPref))
 install(ktorSecurityPlugin(jwtAuth = jwtAuth, appPref = appPref))
 defaultRequest {

 header("Content-Type", "application/json")
 header("AppVersion", appConfig.appVersion)
 header("Accept-Language", appPref.getAppLang().isoFormat)
 header("User-Agent", appConfig.userAgent)
 header("hasTamara", true)
 url(baseUrl)
 }

 install(customLoggerPlugin)

 install(HttpTimeout) {
 requestTimeoutMillis = 30000
 connectTimeoutMillis = 30000
 socketTimeoutMillis = 30000
 }
 }
 }

 private val customLoggerPlugin = createClientPlugin("CustomLoggerPlugin") {
 onRequest { request, content ->

 val curl = toCurl(request)
 logDebug("=============REQUEST==============")
 logDebug("${request.method.value} => ${request.url}")
 logDebug("BODY => ${request.body}")
 logDebug("CURL => $curl")
 logDebug("=============END-REQUEST==============")

 logApiCurl(
 """
 ┌───── API Request ─────
 │ UUID : ${request.headers[APP_UUID_HEADER_KEY]}
 │ cURL : $curl
 └───────────────────────
 """.trimIndent()
 )
 }
 onResponse { response ->
 logApiCurl(
 """
 ┌───── API Response ─────
 │ UUID : ${response.request.headers[APP_UUID_HEADER_KEY]}
 │ URL : ${response.request.url}
 │ Status : ${response.status}
 │ Duration : ${response.responseTime.timestamp - response.requestTime.timestamp}ms
 └────────────────────────
 """.trimIndent()
 )
 }
 }

 private fun toCurl(request: HttpRequestBuilder): String {
 val method = request.method.value
 val url = request.url.buildString()
 val headers = request.headers.entries().joinToString(" ") { (key, values) ->
 values.joinToString(" ") { value -> "-H \"$key: $value\"" }
 }

 val body = when (val content = request.body) {
 is TextContent -> content.text
 is OutgoingContent.ByteArrayContent -> {
 content.bytes().decodeToString()
 String(content.bytes())
 }

 is FormDataContent -> content.formData.entries().joinToString("&") { (key, values) ->
 values.joinToString("&") { value -> "$key=${value.encodeURLParameter()}" }
 }

 else -> ""
 }

 val dataOption = if (body.isNotBlank()) "-d '$body'" else ""
 return "curl -X $method $url $headers $dataOption"
 }


}
