(Android) {\n // JSON Content Negotiation\n install(ContentNegotiation) {\n json(\n Json {\n ignoreUnknownKeys = true\n isLenient = true\n prettyPrint = enableLogging\n encodeDefaults = true\n coerceInputValues = true\n }\n )\n }\n\n // Logging Plugin\n if (enableLogging) {\n install(Logging) {\n logger = object : Logger {\n override fun log(message: String) {\n Log.d(TAG, message)\n }\n }\n level = LogLevel.ALL\n }\n }\n\n // Timeout Plugin\n install(HttpTimeout) {\n requestTimeoutMillis = REQUEST_TIMEOUT\n connectTimeoutMillis = CONNECT_TIMEOUT\n socketTimeoutMillis = SOCKET_TIMEOUT\n }\n\n // Retry Plugin\n install(HttpRequestRetry) {\n maxRetries = MAX_RETRIES\n \n retryIf { _, response ->\n // Retry on specific status codes\n response.status in listOf(\n HttpStatusCode.RequestTimeout,\n HttpStatusCode.TooManyRequests,\n HttpStatusCode.ServiceUnavailable,\n HttpStatusCode.GatewayTimeout\n )\n }\n \n retryOnExceptionIf { _, cause ->\n // Retry on network exceptions\n cause is java.net.SocketTimeoutException ||\n cause is java.net.UnknownHostException ||\n cause is java.io.IOException\n }\n \n delayMillis { retry ->\n // Exponential backoff\n RETRY_DELAY_BASE * (1 shl retry)\n }\n \n modifyRequest { request ->\n // Log retry attempts\n if (enableLogging) {\n Log.d(TAG, \"Retrying request: ${request.url}\")\n }\n }\n }\n\n // Default Request Configuration\n defaultRequest {\n // GitHub API headers\n header(HttpHeaders.Accept, \"application/vnd.github.raw+json\")\n header(HttpHeaders.Authorization, \"Bearer $githubToken\")\n header(HttpHeaders.UserAgent, \"JordanPrayerTimes-WearOS/1.0\")\n \n // Set base URL\n url(BASE_URL)\n }\n\n // Response validation\n expectSuccess = false\n }\n }\n\n /**\n * Helper to build full GitHub API URLs\n */\n fun buildGithubApiUrl(path: String): String {\n return \"$BASE_URL/$REPO_PATH/$path\"\n }\n}\n"}"}}]},{"role":"tool","name":"write","tool_call_id":"toolu_017u9XhE4MjEznJZ3b4ingQt","content":"Wrote contents to /Users/hazemafaneh/S