meUnit.MILLISECONDS)\n writeTimeout(NetworkConfig.Timeouts.REQUEST, TimeUnit.MILLISECONDS)\n retryOnConnectionFailure(true)\n }\n }\n \n // JSON Content Negotiation\n install(ContentNegotiation) {\n json(\n Json {\n ignoreUnknownKeys = true\n isLenient = true\n prettyPrint = enableLogging\n encodeDefaults = true\n coerceInputValues = true\n }\n )\n }\n\n // Logging Plugin\n if (enableLogging) {\n install(Logging) {\n logger = object : Logger {\n override fun log(message: String) {\n Log.d(TAG, message)\n }\n }\n level = LogLevel.ALL\n }\n }\n\n // Retry Plugin\n install(HttpRequestRetry) {\n maxRetries = NetworkConfig.Retry.MAX_RETRIES\n\n retryIf { _, response ->\n // Retry on specific status codes\n response.status in listOf(\n HttpStatusCode.RequestTimeout,\n HttpStatusCode.TooManyRequests,\n HttpStatusCode.ServiceUnavailable,\n HttpStatusCode.GatewayTimeout\n )\n }\n\n retryOnExceptionIf { _, cause ->\n // Retry on network exceptions\n cause is java.net.SocketTimeoutException ||\n cause is java.net.UnknownHostException ||\n cause is java.io.IOException\n }\n\n delayMillis { retry ->\n // Exponential backoff\n NetworkConfig.Retry.BASE_DELAY_MS * (1 shl retry)\n }\n\n modifyRequest { request ->\n // Log retry attempts\n if (enableLogging) {\n Log.d(TAG, \"Retrying request: ${request.url}\")\n }\n }\n }\n\n // Default Request Configuration\n defaultRequest {\n // Set common headers for all requests\n header(HttpHeaders.UserAgent, \"JordanPrayerTimes-WearOS/1.0\")\n }\n\n // Response validation\n expectSuccess = false\n }\n }\n\n /**\n * Helper to build full GitHub API URLs\n */\n fun buildGithubApiUrl(path: String): String {\n return \"${NetworkConfig.GITHUB_BASE_URL}/${NetworkConfig.REPO_PATH}/$path\"\n }\n}\n"}"}}]},{"role":"tool","name":"write","tool_call_id":"toolu_01Xfk4Ew9vVSq2LNME4tJKL4","content":"Wrote contents to /Users/hazemafaneh/StudioProjects/prayer/JordanPrayerTimes/app/src/main/java/com/mbf/wearable/jordanprayertimes/data/remote/KtorSetup.kt.

